class MiniCPMV4_5VisionEmbeddings(nn.Module):
    """
    This is a modified version of `siglip.modelign_siglip.SiglipVisionEmbeddings` to enable images of variable
    resolution.

    The modifications are adapted from [Patch n' Pack: NaViT, a Vision Transformer for any Aspect Ratio and Resolution](https://huggingface.co/papers/2307.06304)
    which allows treating images in their native aspect ratio and without the need to resize them to the same
    fixed size. In particular, we start from the original pre-trained SigLIP model
    (which uses images of fixed-size square images) and adapt it by training on images of variable resolutions.
    """

    def __init__(self, config: MiniCPMV4_5VisionConfig):
        super().__init__()
        self.embed_dim = config.hidden_size
        self.image_size = config.image_size
        self.patch_size = config.patch_size

        self.patch_embedding = nn.Conv2d(
            in_channels=config.num_channels,
            out_channels=self.embed_dim,
            kernel_size=self.patch_size,
            stride=self.patch_size,
            padding="valid",
        )

        self.num_patches_per_side = self.image_size // self.patch_size
        self.num_patches = self.num_patches_per_side**2
        self.num_positions = self.num_patches
        self.position_embedding = nn.Embedding(self.num_positions, self.embed_dim)

    def forward(self, pixel_values: torch.Tensor, patch_position_ids: torch.LongTensor) -> torch.Tensor:
        embeddings = self.patch_embedding(pixel_values).flatten(2).transpose(1, 2)
        boundaries = torch.arange(
            1 / self.num_patches_per_side, 1.0, 1 / self.num_patches_per_side, device=pixel_values.device
        )
        # Bucket each patch by its (row, col) in its slice's 2D patch grid; padding stays at (0, 0)
        step = 1.0 / (patch_position_ids.amax(dim=1, keepdim=True) + 1)
        bucket_coords = torch.bucketize(patch_position_ids * step, boundaries, right=True)
        position_ids = bucket_coords[..., 0] * self.num_patches_per_side + bucket_coords[..., 1]
        return embeddings + self.position_embedding(position_ids)


def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float,
    dropout: float = 0.0,
    **kwargs: Unpack[TransformersKwargs],
):
    if hasattr(module, "num_key_value_groups"):
        key = repeat_kv(key, module.num_key_value_groups)
        value = repeat_kv(value, module.num_key_value_groups)

    attn_weights = torch.matmul(query, key.transpose(2, 3)) * scaling
    if attention_mask is not None:
        attn_weights = attn_weights + attention_mask

    attn_weights = nn.functional.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(batch, num_key_value_heads, n_rep, slen, head_dim)
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


class MiniCPMV4_5VisionAttention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(self, config):
        super().__init__()
        self.config = config
        self.embed_dim = config.hidden_size
        self.num_heads = config.num_attention_heads
        self.head_dim = self.embed_dim // self.num_heads
        if self.head_dim * self.num_heads != self.embed_dim:
            raise ValueError(
                f"embed_dim must be divisible by num_heads (got `embed_dim`: {self.embed_dim} and `num_heads`:"
                f" {self.num_heads})."
            )
        self.scale = self.head_dim**-0.5
        self.dropout = config.attention_dropout

        self.k_proj = nn.Linear(self.embed_dim, self.embed_dim)
        self.v_proj = nn.Linear(self.embed_dim, self.embed_dim)
        self.q_proj = nn.Linear(self.embed_dim, self.embed_dim)
        self.out_proj = nn.Linear(self.embed_dim, self.embed_dim)

        # Ignore copy
        self.is_causal = False

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        **kwargs,
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        """Input shape: Batch x Time x Channel"""

        input_shape = hidden_states.shape[:-1]

        hidden_shape = (*input_shape, -1, self.head_dim)
        queries = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        keys = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        values = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )

        attn_output, attn_weights = attention_interface(
            self,
            queries,
            keys,
            values,
            attention_mask,
            is_causal=self.is_causal,
            scaling=self.scale,
            dropout=0.0 if not self.training else self.dropout,
        )

        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        attn_output = self.out_proj(attn_output)

        return attn_output, attn_weights


class MiniCPMV4_5VisionMLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.activation_fn = ACT2FN[config.hidden_act]
        self.fc1 = nn.Linear(config.hidden_size, config.intermediate_size)
        self.fc2 = nn.Linear(config.intermediate_size, config.hidden_size)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        hidden_states = self.fc1(hidden_states)
        hidden_states = self.activation_fn(hidden_states)
        hidden_states = self.fc2(hidden_states)
        return hidden_states


class MiniCPMV4_5EncoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: MiniCPMV4_5VisionConfig):
        super().__init__()
        self.embed_dim = config.hidden_size
        self.self_attn = MiniCPMV4_5VisionAttention(config)
        self.layer_norm1 = nn.LayerNorm(self.embed_dim, eps=config.layer_norm_eps)
        self.mlp = MiniCPMV4_5VisionMLP(config)
        self.layer_norm2 = nn.LayerNorm(self.embed_dim, eps=config.layer_norm_eps)

    @auto_docstring
    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        residual = hidden_states

        hidden_states = self.layer_norm1(hidden_states)
        hidden_states, _ = self.self_attn(
            hidden_states=hidden_states,
            attention_mask=attention_mask,
            **kwargs,
        )
        hidden_states = residual + hidden_states

        residual = hidden_states
        hidden_states = self.layer_norm2(hidden_states)
        hidden_states = self.mlp(hidden_states)
        hidden_states = residual + hidden_states

        return hidden_states


class MiniCPMV4_5Encoder(nn.Module):
    """
    Transformer encoder consisting of `config.num_hidden_layers` self attention layers. Each layer is a
    [`MiniCPMV4_5EncoderLayer`].

    Args:
        config: MiniCPMV4_5Config
    """

    def __init__(self, config: MiniCPMV4_5Config):
        super().__init__()
        self.config = config
        self.layers = nn.ModuleList([MiniCPMV4_5EncoderLayer(config) for _ in range(config.num_hidden_layers)])
        self.gradient_checkpointing = False

    # Ignore copy
    @auto_docstring
    def forward(
        self,
        inputs_embeds,
        attention_mask: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> BaseModelOutput:
        hidden_states = inputs_embeds
        for encoder_layer in self.layers:
            hidden_states = encoder_layer(
                hidden_states,
                attention_mask,
                **kwargs,
            )

        return BaseModelOutput(last_hidden_state=hidden_states)


@auto_docstring(
    custom_intro="""
    MiniCPMV4_5 vision encoder model that returnss raw image embeddings.
    """
)
class MiniCPMV4_5VisionTransformer(MiniCPMV4_5PreTrainedModel):
    config: MiniCPMV4_5VisionConfig
    input_modalities = ("image",)
    _can_record_outputs = {
        "hidden_states": MiniCPMV4_5EncoderLayer,
        "attentions": MiniCPMV4_5VisionAttention,
    }

    def __init__(self, config: MiniCPMV4_5VisionConfig):
        super().__init__(config)
        embed_dim = config.hidden_size

        self.config = config
        self.embeddings = MiniCPMV4_5VisionEmbeddings(config)
        self.encoder = MiniCPMV4_5Encoder(config)
        self.post_layernorm = nn.LayerNorm(embed_dim, eps=config.layer_norm_eps)

        self.post_init()

    def get_input_embeddings(self):
        return self.embeddings

    def set_input_embeddings(self, value):
        self.embeddings = value

    @merge_with_config_defaults
    @capture_outputs(tie_last_hidden_states=False)
    @auto_docstring
    def forward(
        self,
        pixel_values: torch.Tensor,
        patch_attention_mask: torch.BoolTensor,
        patch_position_ids: torch.LongTensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        patch_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`):
            Which patches are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`):
            `(row, col)` of each patch in its slice's patch grid.
        """
        hidden_states = self.embeddings(pixel_values, patch_position_ids)
        attention_mask = create_bidirectional_mask(
            config=self.config, inputs_embeds=hidden_states, attention_mask=patch_attention_mask
        )
        encoder_outputs = self.encoder(inputs_embeds=hidden_states, attention_mask=attention_mask, **kwargs)
        return BaseModelOutputWithPooling(last_hidden_state=self.post_layernorm(encoder_outputs.last_hidden_state))


class MiniCPMV4_5CrossAttention(nn.Module):
    """
    Multi-headed cross-attention, as in DETR: keys can get position embeddings, values never do. The resampler adds the
    slice's 2D position embedding to the keys only.
    """

    def __init__(
        self,
        config: MiniCPMV4_5Config,
        hidden_size: int,
        num_attention_heads: int,
        dropout: float = 0.0,
        bias: bool = True,
    ):
        super().__init__()
        self.config = config
        self.head_dim = hidden_size // num_attention_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = dropout
        self.is_causal = False

        self.k_proj = nn.Linear(hidden_size, hidden_size, bias=bias)
        self.v_proj = nn.Linear(hidden_size, hidden_size, bias=bias)
        self.q_proj = nn.Linear(hidden_size, hidden_size, bias=bias)
        self.o_proj = nn.Linear(hidden_size, hidden_size, bias=bias)

    def forward(
        self,
        hidden_states: torch.Tensor,
        key_value_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        position_embeddings: torch.Tensor | None = None,
        encoder_position_embeddings: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Position embeddings logic:
        - Queries get position_embeddings
        - Keys get encoder_position_embeddings
        - Values don't get any position embeddings
        """
        query_input_shape = hidden_states.shape[:-1]
        query_hidden_shape = (*query_input_shape, -1, self.head_dim)

        kv_input_shape = key_value_states.shape[:-1]
        kv_hidden_shape = (*kv_input_shape, -1, self.head_dim)

        query_input = hidden_states + position_embeddings if position_embeddings is not None else hidden_states
        key_input = (
            key_value_states + encoder_position_embeddings
            if encoder_position_embeddings is not None
            else key_value_states
        )

        query_states = self.q_proj(query_input).view(query_hidden_shape).transpose(1, 2)
        key_states = self.k_proj(key_input).view(kv_hidden_shape).transpose(1, 2)
        value_states = self.v_proj(key_value_states).view(kv_hidden_shape).transpose(1, 2)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )

        attn_output, attn_weights = attention_interface(
            self,
            query_states,
            key_states,
            value_states,
            attention_mask,
            dropout=0.0 if not self.training else self.attention_dropout,
            scaling=self.scaling,
            **kwargs,
        )

        attn_output = attn_output.reshape(*query_input_shape, -1).contiguous()
        attn_output = self.o_proj(attn_output)
        return attn_output, attn_weights


class MiniCPMV4_5Resampler(nn.Module):
    """
    The resampler of MiniCPM-V 2.6. For videos, each row of keys holds a group of frames, with each frame's timestamp
    embedding added to its keys.
    """

    def __init__(self, config: MiniCPMV4_5Config):
        super().__init__()
        self.config = config
        self.embed_dim = config.text_config.hidden_size
        self.query = nn.Parameter(torch.zeros(config.resampler_n_latents, self.embed_dim))
        self.kv_proj = nn.Linear(config.vision_config.hidden_size, self.embed_dim, bias=False)
        self.ln_q = nn.LayerNorm(self.embed_dim, eps=1e-6)
        self.ln_kv = nn.LayerNorm(self.embed_dim, eps=1e-6)
        self.attn = MiniCPMV4_5CrossAttention(config, self.embed_dim, config.resampler_n_heads)
        self.ln_post = nn.LayerNorm(self.embed_dim, eps=1e-6)
        self.proj = nn.Parameter(torch.zeros(self.embed_dim, self.embed_dim))

    def get_2d_pos_embed(self, patch_position_ids: torch.Tensor) -> torch.Tensor:
        """
        2D sin-cos embedding of `(row, col)` patch positions, shape `(num_slices, max_patches, embed_dim)`. Channels
        are laid out as [sin_w | cos_w | sin_h | cos_h] like the original.
        """
        quarter = self.embed_dim // 4
        omega = torch.arange(quarter, device=patch_position_ids.device, dtype=torch.float32) / quarter
        omega = 1.0 / 10000**omega
        rows = patch_position_ids[..., 0, None].float() * omega
        cols = patch_position_ids[..., 1, None].float() * omega
        return torch.cat([cols.sin(), cols.cos(), rows.sin(), rows.cos()], dim=-1)

    def forward(
        self,
        vision_features: torch.Tensor,
        pixel_attention_mask: torch.Tensor,
        patch_position_ids: torch.Tensor,
        temporal_ids: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        kv = self.ln_kv(self.kv_proj(vision_features))
        pos_embed = self.get_2d_pos_embed(patch_position_ids)
        if temporal_ids is not None:
            temporal = self.get_temporal_pos_embed(temporal_ids)
            pos_embed = (pos_embed.unflatten(1, (temporal_ids.shape[1], -1)) + temporal[:, :, None]).flatten(1, 2)
        pos_embed = (pos_embed * pixel_attention_mask[..., None]).to(kv.dtype)
        queries = self.ln_q(self.query).unsqueeze(0).expand(kv.shape[0], -1, -1)
        attention_mask = create_bidirectional_mask(
            config=self.config,
            inputs_embeds=queries,
            attention_mask=pixel_attention_mask,
            encoder_hidden_states=kv,
        )
        attn_output, _ = self.attn(
            queries, kv, attention_mask=attention_mask, encoder_position_embeddings=pos_embed, **kwargs
        )
        return self.ln_post(attn_output) @ self.proj

    def get_temporal_pos_embed(self, temporal_ids: torch.Tensor) -> torch.Tensor:
        """1D sin-cos embedding of each key's frame timestamp, zero where `temporal_ids` is -1 (padding frames)."""
        half = self.embed_dim // 2
        omega = 1.0 / 10000 ** (torch.arange(half, device=temporal_ids.device, dtype=torch.float32) / half)
        angles = temporal_ids.clamp(min=0)[..., None].float() * omega
        return torch.cat([angles.sin(), angles.cos()], dim=-1) * (temporal_ids >= 0)[..., None]


@auto_docstring(
    custom_intro="""
    The MiniCPMV4_5 model which consists of a vision backbone and a language model, without a language modeling head.
    """
)
class MiniCPMV4_5Model(MiniCPMV4_5PreTrainedModel):
    def __init__(self, config: MiniCPMV4_5Config):
        super().__init__(config)
        self.vision_tower = AutoModel.from_config(config.vision_config)
        self.resampler = MiniCPMV4_5Resampler(config)
        self.language_model = AutoModel.from_config(config.text_config)
        self.post_init()

    @can_return_tuple
    @auto_docstring(custom_intro="Encodes image slices and resamples each one to `config.resampler_n_latents` tokens.")
    def get_image_features(
        self,
        pixel_values: torch.Tensor,
        pixel_attention_mask: torch.Tensor,
        patch_position_ids: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(num_slices, num_channels, patch_size, max_patches * patch_size)`):
            Every image slice of the batch as a single row of patches (as the checkpoint was trained), padded to the
            longest slice, as returned by [`MiniCPMV2_5ImageProcessor`].
        pixel_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`):
            Which patches are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`):
            `(row, col)` of each patch in its slice's patch grid, used by the vision embeddings and the resampler.
        """
        vision_outputs = self.vision_tower(
            pixel_values=pixel_values.to(self.vision_tower.dtype),
            patch_attention_mask=pixel_attention_mask,
            patch_position_ids=patch_position_ids,
            return_dict=True,
            **kwargs,
        )
        vision_outputs.pooler_output = self.resampler(
            vision_outputs.last_hidden_state, pixel_attention_mask, patch_position_ids
        )
        return vision_outputs

    def get_placeholder_mask(
        self, input_ids: torch.LongTensor, inputs_embeds: torch.Tensor, features: torch.Tensor, token_id: int
    ) -> torch.Tensor:
        """
        Obtains the placeholder mask of `token_id` from `input_ids` or `inputs_embeds`, and checks that the placeholder
        token count matches the length of `features`.
        """
        if input_ids is None:
            special_mask = inputs_embeds == self.get_input_embeddings()(
                torch.full((), token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_mask = special_mask.all(-1)
        else:
            special_mask = input_ids == token_id
        n_tokens = special_mask.sum()
        special_mask = special_mask.unsqueeze(-1).to(inputs_embeds.device)
        torch_compilable_check(
            n_tokens * inputs_embeds.shape[-1] == features.numel(),
            f"Multimodal features and tokens do not match, tokens: {n_tokens}, features: {features.shape[0] * features.shape[1]}",
        )
        return special_mask

    @can_return_tuple
    @auto_docstring
    @deprecate_kwarg("past_key_values", "5.40.0", new_name="cache")
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        pixel_values: torch.Tensor | None = None,
        pixel_attention_mask: torch.Tensor | None = None,
        patch_position_ids: torch.Tensor | None = None,
        pixel_values_videos: torch.Tensor | None = None,
        pixel_attention_mask_videos: torch.Tensor | None = None,
        patch_position_ids_videos: torch.Tensor | None = None,
        temporal_ids: torch.Tensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        cache: Cache | None = None,
        inputs_embeds: torch.Tensor | None = None,
        mm_encoder_outputs: dict[str, BaseModelOutputWithPooling] | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | MultimodalBaseModelOutputWithPast:
        r"""
        pixel_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`, *optional*):
            Which patches of `pixel_values` are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`, *optional*):
            `(row, col)` of each patch in its slice's patch grid.
        pixel_attention_mask_videos (`torch.BoolTensor` of shape `(num_frame_slices, max_patches)`, *optional*):
            Which patches of `pixel_values_videos` are real (`True`) rather than padding.
        patch_position_ids_videos (`torch.LongTensor` of shape `(num_frame_slices, max_patches, 2)`, *optional*):
            `(row, col)` of each patch in its frame slice's patch grid.
        temporal_ids (`torch.LongTensor` of shape `(num_groups, max_frames)`, *optional*):
            Timestamp of each frame of each (group, slice), in 0.1 s steps; -1 pads shorter groups.
        """
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")
        if (pixel_values is not None or pixel_values_videos is not None) and mm_encoder_outputs is not None:
            raise ValueError("You cannot specify both pixel_values/pixel_values_videos and mm_encoder_outputs")

        if inputs_embeds is None:
            inputs_embeds = self.get_input_embeddings()(input_ids)

        mm_encoder_outputs = mm_encoder_outputs if mm_encoder_outputs is not None else {}
        if mm_encoder_outputs.get("image") is None and pixel_values is not None:
            mm_encoder_outputs["image"] = self.get_image_features(
                pixel_values=pixel_values,
                pixel_attention_mask=pixel_attention_mask,
                patch_position_ids=patch_position_ids,
                return_dict=True,
                **kwargs,
            )
        if mm_encoder_outputs.get("video") is None and pixel_values_videos is not None:
            mm_encoder_outputs["video"] = self.get_video_features(
                pixel_values_videos=pixel_values_videos,
                pixel_attention_mask_videos=pixel_attention_mask_videos,
                patch_position_ids_videos=patch_position_ids_videos,
                temporal_ids=temporal_ids,
                return_dict=True,
                **kwargs,
            )

        for modality, token_id in (("image", self.config.image_token_id), ("video", self.config.video_token_id)):
            if mm_encoder_outputs.get(modality) is not None:
                features = mm_encoder_outputs[modality].pooler_output.to(inputs_embeds.device, inputs_embeds.dtype)
                mask = self.get_placeholder_mask(input_ids, inputs_embeds, features, token_id)
                inputs_embeds = inputs_embeds.masked_scatter(mask, features)

        outputs = self.language_model(
            attention_mask=attention_mask,
            position_ids=position_ids,
            cache=cache,
            inputs_embeds=inputs_embeds,
            **kwargs,
        )
        return MultimodalBaseModelOutputWithPast(
            **outputs, image_outputs=mm_encoder_outputs.get("image"), video_outputs=mm_encoder_outputs.get("video")
        )

    @can_return_tuple
    @auto_docstring(
        custom_intro="Encodes video frame slices and resamples each group of frames to `config.resampler_n_latents` tokens."
    )
    def get_video_features(
        self,
        pixel_values_videos: torch.Tensor,
        pixel_attention_mask_videos: torch.Tensor,
        patch_position_ids_videos: torch.Tensor,
        temporal_ids: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values_videos (`torch.FloatTensor` of shape `(num_frame_slices, num_channels, patch_size, max_patches * patch_size)`):
            Every frame slice as a single row of patches, padded to the longest, as returned by
            [`MiniCPMV4_5VideoProcessor`]: for each group of frames, for each slice, the group's frames.
        pixel_attention_mask_videos (`torch.BoolTensor` of shape `(num_frame_slices, max_patches)`):
            Which patches are real (`True`) rather than padding.
        patch_position_ids_videos (`torch.LongTensor` of shape `(num_frame_slices, max_patches, 2)`):
            `(row, col)` of each patch in its slice's patch grid.
        temporal_ids (`torch.LongTensor` of shape `(num_groups, max_frames)`):
            Timestamp of each frame of each (group, slice), in 0.1 s steps; -1 pads shorter groups.
        """
        vision_outputs = self.vision_tower(
            pixel_values=pixel_values_videos.to(self.vision_tower.dtype),
            patch_attention_mask=pixel_attention_mask_videos,
            patch_position_ids=patch_position_ids_videos,
            return_dict=True,
            **kwargs,
        )
        # The resampler attends to all frames of a group at once: (num_groups, max_frames * max_patches, ...)
        is_frame = temporal_ids >= 0
        grouped = []
        for frame_values in (vision_outputs.last_hidden_state, pixel_attention_mask_videos, patch_position_ids_videos):
            values = frame_values.new_zeros(*is_frame.shape, *frame_values.shape[1:])
            values[is_frame] = frame_values
            grouped.append(values.flatten(1, 2))
        vision_outputs.pooler_output = self.resampler(*grouped, temporal_ids=temporal_ids)
        return vision_outputs


@auto_docstring(
    custom_intro="""
    The MINICPMV4_5 model which consists of a vision backbone and a language model.
    """
)
class MiniCPMV4_5ForConditionalGeneration(MiniCPMV4_5PreTrainedModel, GenerationMixin):
    _tied_weights_keys = {"lm_head.weight": "model.language_model.embed_tokens.weight"}
    _tp_plan = {"lm_head": "colwise_gather_output"}

    def __init__(self, config: MiniCPMV4_5Config):
        super().__init__(config)
        self.model = MiniCPMV4_5Model(config)
        self.lm_head = nn.Linear(config.text_config.hidden_size, config.text_config.vocab_size, bias=False)
        self.post_init()

    def get_output_embeddings(self) -> nn.Module:
        return self.lm_head

    @auto_docstring
    def get_image_features(
        self,
        pixel_values: torch.Tensor,
        pixel_attention_mask: torch.Tensor,
        patch_position_ids: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(num_slices, num_channels, patch_size, max_patches * patch_size)`):
            Every image slice of the batch as a single row of patches, padded to the longest slice.
        pixel_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`):
            Which patches are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`):
            `(row, col)` of each patch in its slice's patch grid.
        """
        return self.model.get_image_features(
            pixel_values=pixel_values,
            pixel_attention_mask=pixel_attention_mask,
            patch_position_ids=patch_position_ids,
            **kwargs,
        )

    @can_return_tuple
    @auto_docstring
    @deprecate_kwarg("past_key_values", "5.40.0", new_name="cache")
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        pixel_values: torch.Tensor | None = None,
        pixel_attention_mask: torch.Tensor | None = None,
        patch_position_ids: torch.Tensor | None = None,
        pixel_values_videos: torch.Tensor | None = None,
        pixel_attention_mask_videos: torch.Tensor | None = None,
        patch_position_ids_videos: torch.Tensor | None = None,
        temporal_ids: torch.Tensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        cache: Cache | None = None,
        inputs_embeds: torch.Tensor | None = None,
        labels: torch.LongTensor | None = None,
        logits_to_keep: int | torch.Tensor = 0,
        mm_encoder_outputs: dict[str, BaseModelOutputWithPooling] | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | MultimodalCausalLMOutputWithPast:
        r"""
        pixel_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`, *optional*):
            Which patches of `pixel_values` are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`, *optional*):
            `(row, col)` of each patch in its slice's patch grid.
        pixel_attention_mask_videos (`torch.BoolTensor` of shape `(num_frame_slices, max_patches)`, *optional*):
            Which patches of `pixel_values_videos` are real (`True`) rather than padding.
        patch_position_ids_videos (`torch.LongTensor` of shape `(num_frame_slices, max_patches, 2)`, *optional*):
            `(row, col)` of each patch in its frame slice's patch grid.
        temporal_ids (`torch.LongTensor` of shape `(num_groups, max_frames)`, *optional*):
            Timestamp of each frame of each (group, slice), in 0.1 s steps; -1 pads shorter groups.

        Example:

        ```python
        >>> from transformers import AutoModelForImageTextToText, AutoProcessor

        >>> model = AutoModelForImageTextToText.from_pretrained("openbmb/MiniCPM-V-4_5", device_map="auto")
        >>> processor = AutoProcessor.from_pretrained("openbmb/MiniCPM-V-4_5")

        >>> messages = [
        ...     {
        ...         "role": "user",
        ...         "content": [
        ...             {"type": "video", "url": "https://huggingface.co/datasets/hf-internal-testing/fixtures_videos/resolve/main/sample_demo_1.mp4"},
        ...             {"type": "text", "text": "Describe the video."},
        ...         ],
        ...     }
        ... ]
        >>> inputs = processor.apply_chat_template(
        ...     messages,
        ...     add_generation_prompt=True,
        ...     enable_thinking=False,
        ...     tokenize=True,
        ...     return_dict=True,
        ...     return_tensors="pt",
        ... ).to(model.device)
        >>> generated = model.generate(**inputs, max_new_tokens=32)
        >>> processor.post_process_image_text_to_text(generated[:, inputs["input_ids"].shape[1] :])[0]
        ```"""
        outputs = self.model(
            input_ids=input_ids,
            pixel_values=pixel_values,
            pixel_attention_mask=pixel_attention_mask,
            patch_position_ids=patch_position_ids,
            pixel_values_videos=pixel_values_videos,
            pixel_attention_mask_videos=pixel_attention_mask_videos,
            patch_position_ids_videos=patch_position_ids_videos,
            temporal_ids=temporal_ids,
            attention_mask=attention_mask,
            position_ids=position_ids,
            cache=cache,
            inputs_embeds=inputs_embeds,
            mm_encoder_outputs=mm_encoder_outputs,
            **kwargs,
        )
        hidden_states = slice_logits_to_keep(outputs[0], logits_to_keep)
        logits = self.lm_head(hidden_states)

        loss = None
        if labels is not None:
            loss = self.loss_function(
                logits=logits, labels=labels, vocab_size=self.config.text_config.vocab_size, **kwargs
            )
        return MultimodalCausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            cache=outputs.cache,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
            image_outputs=outputs.image_outputs,
            video_outputs=outputs.video_outputs,
        )

